import{_ as a,o as e,c as d,a2 as n}from"./chunks/framework.DPTp4bo7.js";const g=JSON.parse('{"title":"4n卡1s(输出迟滞)现象的解释预测与应用","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/explaining-predicting-and-applying-the-4n-1s-stall"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/explaining-predicting-and-applying-the-4n-1s-stall"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/explaining-predicting-and-applying-the-4n-1s-stall"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/explaining-predicting-and-applying-the-4n-1s-stall"}]]},"headers":[],"relativePath":"zh/explaining-predicting-and-applying-the-4n-1s-stall.md","filePath":"zh/page-fpMndghZj3dpXscC34t8jt.md"}'),i={name:"zh/explaining-predicting-and-applying-the-4n-1s-stall.md"};function s(r,t,l,o,p,c){return e(),d("div",null,[...t[0]||(t[0]=[n('<div class="logistics-content"><span class="logistics-source-anchor" id="_4n卡1s-输出迟滞-现象的解释预测与应用" aria-hidden="true"></span><h1 id="_4n卡1s-输出迟滞-现象的解释预测与应用" tabindex="-1">4n卡1s(输出迟滞)现象的解释预测与应用 <a class="header-anchor" href="#_4n卡1s-输出迟滞-现象的解释预测与应用" aria-label="Permalink to &quot;4n卡1s\\(输出迟滞\\)现象的解释预测与应用&quot;">​</a></h1><blockquote><p>源页面 ID：<code>fpMndghZj3dpXscC34t8jt</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=fpMndghZj3dpXscC34t8jt" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p><span id="source-block-ogOroMAolpZ3oShXTLhIbX"></span></p><span class="logistics-source-anchor" id="应用" aria-hidden="true"></span><h2 id="应用" tabindex="-1">应用： <a class="header-anchor" href="#应用" aria-label="Permalink to &quot;应用：&quot;">​</a></h2><p>传送带的4n卡1s最终导致8n总共卡2s=1物品，所以输出为8n/(8n+1)，最具代表性的结果为n＝3时的24/25，方便起见给出下表速算结果</p><table tabindex="0"><thead><tr><th>1</th><th>8/9</th></tr></thead><tbody><tr><td>2</td><td>16/17</td></tr><tr><td>3</td><td>24/25</td></tr><tr><td>4</td><td>32/33</td></tr><tr><td>5</td><td>40/41</td></tr><tr><td>6</td><td>48/49</td></tr><tr><td>7</td><td>56/57</td></tr><tr><td>8</td><td>64/65</td></tr><tr><td>9</td><td>72/73</td></tr></tbody></table><p>对于管道，由于其流速为传送带的4倍，会出现2n卡0.5s=1流体，输出为2n/(2n+1)，理论输出分母最大2*80+1=161的所有大于1的奇数。</p><p><span id="source-block-QwOGl5cUSHHmcEN43Acq41"></span></p><span class="logistics-source-anchor" id="常用实现结构" aria-hidden="true"></span><h4 id="常用实现结构" tabindex="-1">常用实现结构： <a class="header-anchor" href="#常用实现结构" aria-label="Permalink to &quot;常用实现结构：&quot;">​</a></h4><table tabindex="0"><thead><tr><th></th></tr></thead><tbody><tr><td><img src="/endfield-skydoc/logistics/src/assets/images/img-3e48174d964e16f1.q90-b8448fab1a445965.webp" alt="图片"></td></tr></tbody></table><p>图中没有下游的物流桥应当比下游箱子更晚放置</p><p><span id="source-block-e8EeFYsYFoS9sHQsgKByzz"></span></p><span class="logistics-source-anchor" id="解释预测" aria-hidden="true"></span><h2 id="解释预测" tabindex="-1">解释预测 <a class="header-anchor" href="#解释预测" aria-label="Permalink to &quot;解释预测&quot;">​</a></h2><p>相关内容参见<a href="/endfield-skydoc/zh/introduction-to-analyzing-endfield-logistics-bugs">终末地物流bug分析导论</a></p></div>',1)])])}const b=a(i,[["render",s]]);export{g as __pageData,b as default};
